head.script:
  //
/* Zero-FOUC Dark Mode Switcher */
(function() {
  const currentTheme = localStorage.getItem("theme") || 
    (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
  document.documentElement.setAttribute("data-theme", currentTheme);

  window.toggleTheme = function() {
    const active = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", active);
    localStorage.setItem("theme", active);
    updateThemeIcon();
  };

  function updateThemeIcon() {
    const isDark = document.documentElement.getAttribute("data-theme") === "dark";
    const btn = document.getElementById("theme-toggle-btn");
    if (btn) btn.innerHTML = isDark ? "☀️" : "🌙";
  }

  document.addEventListener("DOMContentLoaded", updateThemeIcon);
})();

  //

body.script:
  //
/* ==========================================
   MOBILE NAVIGATION - Hamburger + Drawer
   - Auto-syncs menu items from Desktop LinkList
   ========================================== */
(function() {
  'use strict';

  var hamburgerBtn = null;
  var navDrawer = null;
  var navDrawerBackdrop = null;
  var navDrawerClose = null;

  function syncDrawerMenu() {
    var desktopMenu = document.querySelector('.nav-menu');
    var drawerMenu = document.querySelector('.nav-drawer-menu');
    if (desktopMenu && drawerMenu && !drawerMenu.children.length) {
      drawerMenu.innerHTML = desktopMenu.innerHTML;
    }
  }

  function syncDrawerLogo() {
    var headerLogoImg = document.querySelector('.site-header .brand-logo img.brand-logo-img');
    var drawerLogo = document.querySelector('.nav-drawer-header .brand-logo');
    if (headerLogoImg && drawerLogo) {
      drawerLogo.innerHTML = headerLogoImg.outerHTML;
    }
  }

  function initMobileNav() {
    hamburgerBtn = document.getElementById('hamburger-btn');
    navDrawer = document.getElementById('nav-drawer');
    navDrawerBackdrop = document.getElementById('nav-drawer-backdrop');
    navDrawerClose = document.getElementById('nav-drawer-close');

    syncDrawerMenu();
    syncDrawerLogo();

    if (!hamburgerBtn || !navDrawer) return;

    hamburgerBtn.addEventListener('click', openDrawer);
    if (navDrawerClose) navDrawerClose.addEventListener('click', closeDrawer);
    if (navDrawerBackdrop) navDrawerBackdrop.addEventListener('click', closeDrawer);

    // Close on Escape key
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeDrawer();
    });
  }

  function openDrawer() {
    if (!navDrawer) return;
    navDrawer.classList.add('is-open');
    if (navDrawerBackdrop) navDrawerBackdrop.classList.add('is-open');
    if (hamburgerBtn) hamburgerBtn.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }

  function closeDrawer() {
    if (!navDrawer) return;
    navDrawer.classList.remove('is-open');
    if (navDrawerBackdrop) navDrawerBackdrop.classList.remove('is-open');
    if (hamburgerBtn) hamburgerBtn.classList.remove('is-open');
    document.body.style.overflow = '';
  }

  // Close drawer on window resize to desktop
  window.addEventListener('resize', function() {
    if (window.innerWidth > 768) closeDrawer();
  });

  document.addEventListener('DOMContentLoaded', initMobileNav);
})();


/* ==========================================
   SEARCH MODAL
   ========================================== */
(function() {
  'use strict';

  var searchOverlay = null;
  var searchInput = null;
  var searchOpenBtn = null;
  var searchCloseBtn = null;
  var searchForm = null;

  function initSearchModal() {
    searchOverlay = document.getElementById('search-modal-overlay');
    searchInput = document.getElementById('search-input');
    searchOpenBtn = document.getElementById('search-open-btn');
    searchCloseBtn = document.getElementById('search-close-btn');
    searchForm = document.getElementById('search-form');

    if (!searchOverlay) return;

    if (searchOpenBtn) {
      searchOpenBtn.addEventListener('click', openSearch);
    }
    if (searchCloseBtn) {
      searchCloseBtn.addEventListener('click', closeSearch);
    }
    // Close on backdrop click
    searchOverlay.addEventListener('click', function(e) {
      if (e.target === searchOverlay) closeSearch();
    });
    // Close on Escape
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeSearch();
    });
    // Handle form submit → Blogger search
    if (searchForm) {
      searchForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var query = searchInput ? searchInput.value.trim() : '';
        if (query) {
          window.location.href = '/search?q=' + encodeURIComponent(query);
        }
      });
    }
  }

  function openSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.add('is-open');
    document.body.style.overflow = 'hidden';
    // Focus input after animation
    setTimeout(function() {
      if (searchInput) searchInput.focus();
    }, 200);
  }

  function closeSearch() {
    if (!searchOverlay) return;
    searchOverlay.classList.remove('is-open');
    document.body.style.overflow = '';
  }

  document.addEventListener('DOMContentLoaded', initSearchModal);
})();


/* ==========================================
   ARCHIVE PAGE (MỤC LỤC TOÀN THƯ) — v3.0
   Đặc tả: specs/TIMELINE_ARCHIVE_PAGE_SPECIFICATION.md (FEAT-TIMELINE-PAGE-V3)
   - Tự động nhận diện trang tĩnh /p/muc-luc.html hoặc container #editorial-archive-app
   - Thu thập & Cache Blogger JSON Feed API (500 bài)
   - Tìm kiếm tức thì tiếng Việt có dấu/không dấu (Debounce 150ms)
   - Lọc theo Category Pills + Accordion đóng/mở theo Năm
   - Hỗ trợ URL Query Parameters: ?q=, ?cat=, ?year=
   ========================================== */

(function () {
  'use strict';

  var CACHE_KEY = 'blogger_archive_posts';
  var allPosts = [];
  var activeCategory = 'all';
  var searchQuery = '';
  var expandedYears = {}; // year -> boolean
  var searchDebounceTimer = null;
  var isAppMounted = false;

  // Helper: Loại bỏ dấu tiếng Việt để tìm kiếm không dấu
  function removeVietnameseDiacritics(str) {
    if (!str) return '';
    return str
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd')
      .replace(/Đ/g, 'D')
      .toLowerCase()
      .trim();
  }

  // Format ngày DD/MM từ chuỗi ISO
  function formatDateStr(isoStr) {
    if (!isoStr) return '';
    var d = new Date(isoStr);
    if (isNaN(d.getTime())) return '';
    var dd = String(d.getDate()).padStart(2, '0');
    var mm = String(d.getMonth() + 1).padStart(2, '0');
    return dd + '/' + mm;
  }

  // Format năm YYYY từ chuỗi ISO
  function getYearFromDate(isoStr) {
    if (!isoStr) return new Date().getFullYear();
    var d = new Date(isoStr);
    return isNaN(d.getTime()) ? new Date().getFullYear() : d.getFullYear();
  }

  // Kiểm tra xem hiện tại có phải trang Mục Lục hay không
  function isArchivePage() {
    var pathname = window.location.pathname.toLowerCase();
    var href = window.location.href.toLowerCase();
    var container = document.getElementById('editorial-archive-app');

    return (
      Boolean(container) ||
      pathname.endsWith('/p/muc-luc.html') ||
      pathname.endsWith('/p/archive.html') ||
      href.indexOf('/p/muc-luc.html') !== -1 ||
      href.indexOf('/p/archive.html') !== -1 ||
      window.location.hash === '#archive'
    );
  }

  // Thu thập dữ liệu bài viết (Cache -> API -> Fallback Mock Data)
  function loadArchiveData(callback) {
    // 1. Kiểm tra Cache trong sessionStorage
    try {
      var cached = sessionStorage.getItem(CACHE_KEY);
      if (cached) {
        var parsed = JSON.parse(cached);
        if (Array.isArray(parsed) && parsed.length > 0) {
          allPosts = parsed;
          if (callback) callback(allPosts);
          return;
        }
      }
    } catch (e) {
      console.warn('[Archive] sessionStorage error:', e);
    }

    // 2. Thử tải Blogger JSON Feed API
    var feedUrl = '/feeds/posts/summary?alt=json&max-results=500';
    var isPreviewOrLocal =
      window.location.protocol === 'file:' ||
      window.location.hostname === 'localhost' ||
      window.location.hostname === '127.0.0.1';

    if (!isPreviewOrLocal) {
      fetch(feedUrl)
        .then(function (res) {
          if (!res.ok) throw new Error('Feed fetch failed: ' + res.status);
          return res.json();
        })
        .then(function (data) {
          var entries = (data.feed && data.feed.entry) || [];
          var posts = [];
          entries.forEach(function (entry) {
            var allLabels = [];
            if (entry.category && entry.category.length > 0) {
              allLabels = entry.category.map(function(c) { return c.term || ''; });
            }

            // QUY TẮC VÀNG: Bỏ qua bài viết nếu TẤT CẢ nhãn đều bắt đầu bằng "@"
            var isExclusiveFeature = allLabels.length > 0 && allLabels.every(function(l) { return l.indexOf('@') === 0; });
            if (isExclusiveFeature) return;

            var title = (entry.title && entry.title.$t) || 'Bài viết không tiêu đề';
            var postUrl = '#';
            if (entry.link) {
              var altLink = entry.link.find(function (l) { return l.rel === 'alternate'; });
              if (altLink) postUrl = altLink.href;
            }
            var published = (entry.published && entry.published.$t) || '';
            var year = getYearFromDate(published);
            var dateStr = formatDateStr(published);
            var timestamp = published ? new Date(published).getTime() : 0;

            var category = 'Chưa phân loại';
            var aiType = null; // Nhãn AI (ai:assisted, ai:product, ai:generated)
            if (allLabels.length > 0) {
              var normalLabels = allLabels.filter(function(l) {
                var lower = l.toLowerCase();
                return l.indexOf('@') !== 0 && !lower.startsWith('ai:') && !lower.startsWith('ai-');
              });
              category = normalLabels.length > 0 ? normalLabels[0] : allLabels[0];

              // Trích xuất nhãn AI nếu có
              allLabels.forEach(function(l) {
                if (!aiType) {
                  var lower = l.toLowerCase().replace(/-/g, ':');
                  if (lower.startsWith('ai:')) aiType = lower;
                }
              });
            }
            // Lọc sạch các tiền tố đặc biệt nếu còn sót lại
            category = category.replace(/^[@#_~]+/, '').trim();

            posts.push({
              title: title,
              url: postUrl,
              year: year,
              dateStr: dateStr,
              category: category,
              aiType: aiType,
              timestamp: timestamp
            });
          });

          // Sắp xếp giảm dần theo thời gian
          posts.sort(function (a, b) { return b.timestamp - a.timestamp; });

          allPosts = posts;
          try {
            sessionStorage.setItem(CACHE_KEY, JSON.stringify(posts));
          } catch (e) {}

          if (callback) callback(allPosts);
        })
        .catch(function (err) {
          console.warn('[Archive] Feed fetch failed, using fallback:', err);
          useFallbackData(callback);
        });
    } else {
      useFallbackData(callback);
    }
  }

  // Fallback dữ liệu mock khi chạy local preview hoặc lỗi feed
  function useFallbackData(callback) {
    if (window.__TIMELINE_MOCK_POSTS__ && window.__TIMELINE_MOCK_POSTS__.length > 0) {
      allPosts = window.__TIMELINE_MOCK_POSTS__.slice();
    } else {
      // Cố gắng trích xuất các bài viết từ DOM nếu có
      var domCards = document.querySelectorAll('.posts-feed .post-card');
      if (domCards.length > 0) {
        allPosts = Array.from(domCards).map(function (card, index) {
          var titleEl = card.querySelector('.post-card-title a, .post-card-title');
          var badgeEl = card.querySelector('.post-badge');
          var dateEl = card.querySelector('time');
          var title = titleEl ? titleEl.textContent.trim() : 'Bài viết #' + (index + 1);
          var postUrl = titleEl && titleEl.getAttribute('href') ? titleEl.getAttribute('href') : '#';
          var category = badgeEl ? badgeEl.textContent.trim() : 'Góc Nhìn';
          var rawDate = dateEl ? dateEl.getAttribute('datetime') || dateEl.textContent : '';
          var year = getYearFromDate(rawDate);
          var dateStr = formatDateStr(rawDate) || '15/08';
          var timestamp = rawDate ? new Date(rawDate).getTime() : Date.now() - index * 86400000 * 5;
          return {
            title: title,
            url: postUrl,
            year: year,
            dateStr: dateStr,
            category: category,
            aiType: card.getAttribute('data-ai-type') || null,
            timestamp: timestamp
          };
        });
      } else {
        allPosts = [];
      }
    }

    allPosts.sort(function (a, b) { return b.timestamp - a.timestamp; });
    if (callback) callback(allPosts);
  }

  // Đọc URL Query Parameters (?q=, ?cat=, ?year=)
  function parseUrlParams() {
    var params = new URLSearchParams(window.location.search);
    var q = params.get('q');
    var cat = params.get('cat');
    var yr = params.get('year');

    if (q) searchQuery = q.trim();
    if (cat) activeCategory = cat.trim();
    if (yr) {
      var yNum = parseInt(yr, 10);
      if (!isNaN(yNum)) {
        expandedYears = {};
        expandedYears[yNum] = true;
      }
    }
  }

  // Cập nhật URL Query Parameters mà không reload trang
  function syncUrlParams() {
    try {
      var url = new URL(window.location.href);
      if (searchQuery) {
        url.searchParams.set('q', searchQuery);
      } else {
        url.searchParams.delete('q');
      }

      if (activeCategory && activeCategory !== 'all') {
        url.searchParams.set('cat', activeCategory);
      } else {
        url.searchParams.delete('cat');
      }

      window.history.replaceState({}, '', url.toString());
    } catch (e) {}
  }

  // Cập nhật các huy hiệu thống kê (Stats Badges)
  function updateStatsBadges(postsToCount) {
    var statPosts = document.getElementById('archive-stat-posts');
    var statYears = document.getElementById('archive-stat-years');
    var statCats = document.getElementById('archive-stat-cats');

    var list = postsToCount || allPosts;
    var totalPosts = list.length;

    var yearsSet = new Set();
    var catsSet = new Set();
    list.forEach(function (p) {
      if (p.year) yearsSet.add(p.year);
      if (p.category && p.category !== 'Chưa phân loại') catsSet.add(p.category);
    });

    if (statPosts) statPosts.innerHTML = '<strong>📚 ' + totalPosts + '</strong> Bài viết';
    if (statYears) statYears.innerHTML = '<strong>🗓️ ' + yearsSet.size + '</strong> Năm xuất bản';
    if (statCats) statCats.innerHTML = '<strong>🏷️ ' + catsSet.size + '</strong> Chủ đề';
  }

  // Khởi tạo và render Category Pills
  function renderCategoryPills(container) {
    var pillsContainer = container.querySelector('#archive-cat-pills');
    if (!pillsContainer) return;

    // Đếm bài viết theo category
    var catCounts = { all: allPosts.length };
    allPosts.forEach(function (p) {
      var cat = p.category || 'Chưa phân loại';
      catCounts[cat] = (catCounts[cat] || 0) + 1;
    });

    var categories = Object.keys(catCounts).filter(function (c) { return c !== 'all'; });
    categories.sort(function (a, b) { return catCounts[b] - catCounts[a]; });

    var html = '';
    // Pill Tất cả
    var isAllActive = activeCategory === 'all' || !activeCategory;
    html += '<button type="button" class="archive-cat-pill ' + (isAllActive ? 'is-active' : '') + '" data-cat="all">';
    html += '✦ Tất cả <span class="pill-count">(' + catCounts.all + ')</span>';
    html += '</button>';

    categories.forEach(function (cat) {
      var isActive = activeCategory.toLowerCase() === cat.toLowerCase();
      html += '<button type="button" class="archive-cat-pill ' + (isActive ? 'is-active' : '') + '" data-cat="' + escapeHtml(cat) + '">';
      html += escapeHtml(cat) + ' <span class="pill-count">(' + catCounts[cat] + ')</span>';
      html += '</button>';
    });

    pillsContainer.innerHTML = html;

    // Gắn sự kiện click cho từng pill
    var pillBtns = pillsContainer.querySelectorAll('.archive-cat-pill');
    pillBtns.forEach(function (btn) {
      btn.addEventListener('click', function () {
        pillBtns.forEach(function (b) { b.classList.remove('is-active'); });
        btn.classList.add('is-active');
        activeCategory = btn.getAttribute('data-cat') || 'all';
        syncUrlParams();
        applyFilterAndRender(container);
      });
    });
  }

  // Lọc bài viết theo searchQuery & activeCategory
  function filterPosts() {
    var queryRaw = searchQuery.toLowerCase().trim();
    var queryNormalized = removeVietnameseDiacritics(searchQuery);

    return allPosts.filter(function (post) {
      // 1. Lọc theo chuyên mục
      if (activeCategory !== 'all') {
        var postCat = (post.category || '').toLowerCase();
        if (postCat !== activeCategory.toLowerCase()) {
          return false;
        }
      }

      // 2. Lọc theo từ khóa tìm kiếm
      if (!queryRaw) return true;

      var titleRaw = (post.title || '').toLowerCase();
      var titleNormalized = removeVietnameseDiacritics(post.title || '');
      var catNormalized = removeVietnameseDiacritics(post.category || '');
      var yearStr = String(post.year);
      var dateStr = post.dateStr || '';

      var matchTitle = titleRaw.indexOf(queryRaw) !== -1 || titleNormalized.indexOf(queryNormalized) !== -1;
      var matchCat = catNormalized.indexOf(queryNormalized) !== -1;
      var matchYear = yearStr.indexOf(queryRaw) !== -1;
      var matchDate = dateStr.indexOf(queryRaw) !== -1;

      return matchTitle || matchCat || matchYear || matchDate;
    });
  }

  // Nhóm bài viết theo Năm (giảm dần)
  function groupPostsByYear(posts) {
    var groups = {};
    posts.forEach(function (p) {
      var yr = p.year || new Date().getFullYear();
      if (!groups[yr]) groups[yr] = [];
      groups[yr].push(p);
    });

    // Mảng các năm sắp xếp giảm dần
    var years = Object.keys(groups).map(Number);
    years.sort(function (a, b) { return b - a; });

    return years.map(function (yr) {
      return {
        year: yr,
        posts: groups[yr]
      };
    });
  }

  // Render danh sách cây năm và thẻ bài viết phẳng
  function applyFilterAndRender(container) {
    var body = container.querySelector('#archive-app-body');
    if (!body) return;

    var filtered = filterPosts();
    var yearGroups = groupPostsByYear(filtered);

    // Nếu không có bài viết nào phù hợp
    if (yearGroups.length === 0) {
      body.innerHTML = [
        '<div class="archive-empty-state">',
        '  <div class="archive-empty-icon">🔍</div>',
        '  <h3 class="archive-empty-title">Không tìm thấy bài viết nào phù hợp</h3>',
        '  <p class="archive-empty-desc">Thử tìm kiếm với từ khóa khác hoặc bấm để xem toàn bộ bài viết.</p>',
        '  <button type="button" class="archive-btn-reset" id="archive-reset-btn">↺ Xem tất cả bài viết</button>',
        '</div>'
      ].join('');

      var resetBtn = body.querySelector('#archive-reset-btn');
      if (resetBtn) {
        resetBtn.addEventListener('click', function () {
          searchQuery = '';
          activeCategory = 'all';
          var searchInput = container.querySelector('#archive-search-input');
          var clearBtn = container.querySelector('#archive-search-clear');
          if (searchInput) searchInput.value = '';
          if (clearBtn) clearBtn.style.display = 'none';

          var tabs = document.querySelectorAll('.category-tabs-bar .tab-pill');
          tabs.forEach(function (t, idx) {
            t.classList.toggle('active', idx === 0);
          });

          syncUrlParams();
          applyFilterAndRender(container);
        });
      }
      return;
    }

    // Xây dựng cây dòng thời gian
    var html = '';
    yearGroups.forEach(function (group, gIdx) {
      // Mặc định mở tất cả các năm (trừ khi đã có trạng thái lưu)
      var yr = group.year;
      var isExpanded = expandedYears[yr] !== undefined ? expandedYears[yr] : true;

      html += '<div class="archive-year-group ' + (isExpanded ? 'is-expanded' : 'is-collapsed') + '" data-year="' + yr + '">';

      // Node Năm (Header) - Tinh gọn, chỉ có số năm, đường kẻ và chevron
      html += '<div class="archive-year-header" role="button" tabindex="0" aria-expanded="' + isExpanded + '" aria-controls="year-posts-' + yr + '">';
      html += '  <div class="archive-year-title-wrap">';
      html += '    <span class="archive-year-num">' + yr + '</span>';
      html += '  </div>';
      html += '  <div class="archive-year-line" aria-hidden="true"></div>';
      html += '  <div class="archive-year-chevron" aria-hidden="true">';
      html += '    <svg viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>';
      html += '  </div>';
      html += '</div>';

      // Danh sách thẻ bài viết phẳng
      html += '<div class="archive-year-posts" id="year-posts-' + yr + '">';
      group.posts.forEach(function (post) {
        var aiAttr = post.aiType ? ' data-ai-type="' + post.aiType + '"' : '';
        html += '<a class="archive-post-card" href="' + escapeHtml(post.url) + '"' + aiAttr + '>';
        // Cột 1: Chuyên mục
        html += '  <span class="archive-post-cat-pill">' + escapeHtml(post.category || 'Góc Nhìn') + '</span>';
        // Cột 2: Tiêu đề
        html += '  <span class="archive-post-card-title">' + escapeHtml(post.title) + '</span>';
        // Cột 2b: AI Micro Badge (nếu có nhãn AI)
        if (post.aiType && window.AITransparency) {
          var lang = (typeof localStorage !== 'undefined' && localStorage.getItem('user_lang')) || 'vi';
          html += window.AITransparency.renderAIBadge(post.aiType, 'micro', lang);
        }
        // Cột 3: Ngày đăng + Mũi tên
        html += '  <div class="archive-post-meta">';
        html += '    <span class="archive-post-date">📅 ' + escapeHtml(post.dateStr) + '</span>';
        html += '    <span class="archive-post-arrow" aria-hidden="true">→</span>';
        html += '  </div>';
        html += '</a>';
      });
      html += '</div>'; // /.archive-year-posts

      html += '</div>'; // /.archive-year-group
    });

    body.innerHTML = html;

    // Gắn sự kiện click Accordion cho các Node Năm
    var yearHeaders = body.querySelectorAll('.archive-year-header');
    yearHeaders.forEach(function (header) {
      function toggleYear() {
        var groupEl = header.closest('.archive-year-group');
        if (!groupEl) return;
        var yr = groupEl.getAttribute('data-year');
        var willExpand = !groupEl.classList.contains('is-expanded');

        groupEl.classList.toggle('is-expanded', willExpand);
        groupEl.classList.toggle('is-collapsed', !willExpand);
        header.setAttribute('aria-expanded', willExpand);
        expandedYears[yr] = willExpand;
      }

      header.addEventListener('click', toggleYear);
      header.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          toggleYear();
        }
      });
    });
  }

  // Khởi tạo toàn bộ sự kiện tìm kiếm & điều khiển
  function bindArchiveEvents(container) {
    var searchInput = container.querySelector('#archive-search-input');
    var clearBtn = container.querySelector('#archive-search-clear');
    var expandAllBtn = container.querySelector('#archive-expand-all');
    var collapseAllBtn = container.querySelector('#archive-collapse-all');

    // Khởi tạo giá trị ban đầu nếu có từ URL
    if (searchInput) {
      if (searchQuery) {
        searchInput.value = searchQuery;
        if (clearBtn) clearBtn.style.display = 'flex';
      }

      searchInput.addEventListener('input', function () {
        searchQuery = searchInput.value;
        if (clearBtn) {
          clearBtn.style.display = searchQuery.length > 0 ? 'flex' : 'none';
        }

        clearTimeout(searchDebounceTimer);
        searchDebounceTimer = setTimeout(function () {
          syncUrlParams();
          applyFilterAndRender(container);
        }, 150); // Debounce 150ms theo spec
      });
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', function () {
        searchQuery = '';
        if (searchInput) {
          searchInput.value = '';
          searchInput.focus();
        }
        clearBtn.style.display = 'none';
        syncUrlParams();
        applyFilterAndRender(container);
      });
    }

    // Mở tất cả các năm
    if (expandAllBtn) {
      expandAllBtn.addEventListener('click', function () {
        var yearGroups = container.querySelectorAll('.archive-year-group');
        yearGroups.forEach(function (g) {
          var yr = g.getAttribute('data-year');
          g.classList.remove('is-collapsed');
          g.classList.add('is-expanded');
          var hdr = g.querySelector('.archive-year-header');
          if (hdr) hdr.setAttribute('aria-expanded', 'true');
          expandedYears[yr] = true;
        });
      });
    }

    // Thu gọn tất cả các năm
    if (collapseAllBtn) {
      collapseAllBtn.addEventListener('click', function () {
        var yearGroups = container.querySelectorAll('.archive-year-group');
        yearGroups.forEach(function (g) {
          var yr = g.getAttribute('data-year');
          g.classList.remove('is-expanded');
          g.classList.add('is-collapsed');
          var hdr = g.querySelector('.archive-year-header');
          if (hdr) hdr.setAttribute('aria-expanded', 'false');
          expandedYears[yr] = false;
        });
      });
    }
  }

  // Tạo khung HTML hoàn chỉnh cho Dedicated Archive Page nếu chưa có sẵn
  function createArchiveStructure(container) {
    if (container.querySelector('.archive-search-wrap')) {
      return; // Đã có cấu trúc sẵn
    }

    var html = [
      '<!-- Thanh Tìm Kiếm Tức Thì -->',
      '<div class="archive-search-wrap">',
      '  <span class="archive-search-icon" aria-hidden="true">🔍</span>',
      '  <input class="archive-search-input" id="archive-search-input" type="search"',
      '         placeholder="Nhập từ khóa tìm tên bài, chủ đề hoặc năm (VD: 2025, sách, thói quen)..."',
      '         autocomplete="off" aria-label="Tìm kiếm bài viết"/>',
      '  <button type="button" class="archive-search-clear" id="archive-search-clear" aria-label="Xóa tìm kiếm" style="display:none;">✕</button>',
      '</div>',
      '',
      '<!-- Khung danh sách bài viết -->',
      '<div id="archive-app-body" class="archive-tree-container" aria-live="polite">',
      '  <div class="archive-loading">',
      '    <div class="archive-spinner"></div>',
      '    <span>Đang đồng bộ danh mục bài viết...</span>',
      '  </div>',
      '</div>'
    ].join('\n');

    container.innerHTML = html;
  }

  // Kết nối thanh nhãn Chuyên mục dưới banner (.category-tabs-bar) để lọc bài viết
  function bindCategoryTabs(container) {
    var tabs = document.querySelectorAll('.category-tabs-bar .tab-pill');
    tabs.forEach(function (pill) {
      if (pill._archiveBound) return;
      pill._archiveBound = true;

      pill.addEventListener('click', function (e) {
        var appEl = document.getElementById('editorial-archive-app');
        if (appEl && appEl.offsetParent !== null) {
          e.preventDefault();
          tabs.forEach(function (t) { t.classList.remove('active'); });
          pill.classList.add('active');

          var catText = pill.textContent.replace('✦', '').trim();
          activeCategory = (catText === 'Tất cả') ? 'all' : catText;

          syncUrlParams();
          applyFilterAndRender(appEl);
        }
      });
    });
  }

  // Escape HTML để ngăn ngừa XSS
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // Khởi động toàn bộ ứng dụng Mục Lục
  function mountArchiveApp(targetEl) {
    var container = targetEl || document.getElementById('editorial-archive-app');
    if (!container) return;

    container.classList.add('editorial-archive-page');
    createArchiveStructure(container);
    parseUrlParams();
    bindArchiveEvents(container);
    bindCategoryTabs(container);

    loadArchiveData(function (posts) {
      applyFilterAndRender(container);
    });

    isAppMounted = true;
  }

  // Khởi chạy khi DOM sẵn sàng
  function init() {
    if (isArchivePage()) {
      var appEl = document.getElementById('editorial-archive-app');
      if (appEl) {
        mountArchiveApp(appEl);
      }
    }
  }

  // Export API toàn cục để preview.html hoặc router có thể gọi trực tiếp
  window.initArchivePage = function (targetEl) {
    mountArchiveApp(targetEl);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();


/* ==========================================
   AUTO TABLE OF CONTENTS (TOC) GENERATOR
   - Extracts visible h2, h3 from .post-body
   - Supports bilingual content filtering & sync
   - Collapsible with toggle button
   - Smooth scroll to section on click
   - Highlights active section during scroll
   ========================================== */
(function() {
  'use strict';

  var tocContainer = null;
  var isCollapsed = false;
  var observer = null;

  function getVisibleHeadings() {
    var postBody = document.querySelector('.post-body');
    if (!postBody) return [];

    var allHeadings = postBody.querySelectorAll('h2, h3');
    var visibleHeadings = [];

    allHeadings.forEach(function(heading) {
      var parent = heading.parentElement;
      var isHidden = false;
      while (parent && parent !== postBody) {
        if (parent.style.display === 'none' || (parent.hasAttribute('data-lang') && parent.style.display === 'none')) {
          isHidden = true;
          break;
        }
        parent = parent.parentElement;
      }
      if (!isHidden) {
        visibleHeadings.push(heading);
      }
    });

    return visibleHeadings;
  }

  function initTOC() {
    var postBody = document.querySelector('.post-body');
    tocContainer = document.getElementById('auto-toc');
    if (!postBody || !tocContainer) return;

    var headings = getVisibleHeadings();
    if (headings.length < 2) {
      tocContainer.style.display = 'none';
      return;
    }
    tocContainer.style.display = '';

    // Assign IDs to headings
    headings.forEach(function(heading, idx) {
      if (!heading.id) {
        var slug = heading.innerText
          .toLowerCase()
          .replace(/[^a-z0-9À-ɏḀ-ỿ\s-]/g, '')
          .replace(/\s+/g, '-')
          .replace(/-+/g, '-')
          .trim();
        heading.id = slug || ('heading-' + idx);
      }
    });

    // Detect language for title
    var isEn = document.querySelector('.lang-btn-en.active') !== null;
    var tocTitleText = isEn ? '📑 Table of Contents' : '📑 Mục Lục Bài Viết';

    // Build TOC HTML
    var html = '<div class="toc-title" onclick="toggleTocList()" role="button" tabindex="0">' +
               '<span>' + tocTitleText + '</span>' +
               '<span class="toc-toggle-icon" id="toc-toggle-icon">' + (isCollapsed ? '▼' : '▲') + '</span>' +
               '</div>' +
               '<ul class="toc-list" id="toc-list-items"' + (isCollapsed ? ' style="display:none;"' : '') + '>';

    headings.forEach(function(heading) {
      var tagClass = heading.tagName.toLowerCase() === 'h3' ? 'toc-h3' : 'toc-h2';
      html += '<li class="' + tagClass + '">' +
              '<a href="#' + heading.id + '" onclick="scrollToSection(event, \'' + heading.id + '\')">' +
              heading.innerText + '</a></li>';
    });

    html += '</ul>';
    tocContainer.innerHTML = html;

    // Keyboard accessibility for TOC title
    var tocTitle = tocContainer.querySelector('.toc-title');
    if (tocTitle) {
      tocTitle.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') toggleTocList();
      });
    }

    // Activate IntersectionObserver for highlight
    initTOCObserver(headings);
  }

  // Toggle open/collapse
  window.toggleTocList = function() {
    var list = document.getElementById('toc-list-items');
    var icon = document.getElementById('toc-toggle-icon');
    if (!list) return;
    isCollapsed = !isCollapsed;
    list.style.display = isCollapsed ? 'none' : '';
    if (icon) icon.innerText = isCollapsed ? '▼' : '▲';
  };

  // Smooth scroll to heading
  window.scrollToSection = function(e, id) {
    e.preventDefault();
    var target = document.getElementById(id);
    if (!target) return;
    var offset = 80; // header height + gap
    var top = target.getBoundingClientRect().top + window.pageYOffset - offset;
    window.scrollTo({ top: top, behavior: 'smooth' });
    if (history.replaceState) {
      history.replaceState(null, null, '#' + id);
    }
  };

  // Highlight active TOC item on scroll
  function initTOCObserver(headings) {
    if (!('IntersectionObserver' in window)) return;
    if (observer) observer.disconnect();

    var activeId = null;

    observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          activeId = entry.target.id;
        }
      });

      if (activeId) {
        var links = document.querySelectorAll('.toc-list a');
        links.forEach(function(link) {
          if (link.getAttribute('href') === '#' + activeId) {
            link.classList.add('active');
          } else {
            link.classList.remove('active');
          }
        });
      }
    }, {
      rootMargin: '-80px 0px -60% 0px',
      threshold: 0
    });

    headings.forEach(function(heading) {
      observer.observe(heading);
    });
  }

  // Re-generate TOC on language change
  window.addEventListener('languageChanged', function() {
    initTOC();
  });

  document.addEventListener('DOMContentLoaded', initTOC);
})();


/* ==========================================
   IN-POST & THEME BILINGUAL SWITCHER (UNIFIED ORCHESTRATOR)
   - Switches VI / EN content blocks
   - Parses "VI | EN" syntax in menus, widgets
   - Translates static dictionary terms
   - Saves preference to localStorage
   - Emits languageChanged event for Auto-TOC re-render
   ========================================== */
(function() {
  'use strict';

  var STORAGE_KEY = 'user_lang';

  const CORE_I18N = {
    vi: {
      searchPlaceholder: 'Tìm kiếm bài viết...',
      readingTime: 'phút đọc',
      tableOfContents: 'Mục Lục Bài Viết',
      previousPost: '« Bài trước',
      nextPost: 'Bài sau »',
      shareTitle: 'Chia sẻ bài viết:',
      copiedLink: 'Đã sao chép liên kết!',
      aboutAuthor: 'Về Tác Giả',
      buyMeACoffee: 'Mời tôi ly cà phê',
      newsletterTitle: 'Nhận bài viết mới',
      newsletterDesc: 'Nhận thông báo khi có bài viết mới qua email.',
      subscribeBtn: 'Đăng Ký',
      olderPosts: 'Cũ hơn »',
      newsletterSubDesc: 'Đăng ký để nhận thông báo khi có bài viết mới. Không spam, chỉ nội dung chất lượng.',
      backToTop: '↑ Lên đầu trang',
      copyrightSuffix: 'Tất cả quyền được bảo lưu.',
      aiDisclosureDetails: 'Xem chi tiết',
    },
    en: {
      searchPlaceholder: 'Search articles...',
      readingTime: 'min read',
      tableOfContents: 'Table of Contents',
      previousPost: '« Previous Post',
      nextPost: 'Next Post »',
      shareTitle: 'Share this post:',
      copiedLink: 'Link copied to clipboard!',
      aboutAuthor: 'About The Author',
      buyMeACoffee: 'Buy me a coffee',
      newsletterTitle: 'Newsletter',
      newsletterDesc: 'Get thoughtful articles delivered to your inbox.',
      subscribeBtn: 'Subscribe',
      olderPosts: 'Older Posts »',
      newsletterSubDesc: 'Subscribe to get notified of new articles. No spam, only quality content.',
      backToTop: '↑ Back to top',
      copyrightSuffix: 'All rights reserved.',
      aiDisclosureDetails: 'Details',
    }
  };

  function initBilingual() {
    // Restore preferred language from localStorage
    var preferred = localStorage.getItem(STORAGE_KEY) || 'vi';
    applyLanguage(preferred, false);
  }

  function applyBilingualElements(lang) {
    // Bộ chọn toàn bộ các phần tử hỗ trợ cú pháp VI | EN
    // Bao gồm: data-bilingual="true", badge thẻ bài, tab chủ đề, pill timeline, breadcrumbs (spec §4.2.A)
    const targets = document.querySelectorAll(
      '[data-bilingual="true"], .post-badge, .tab-pill, .archive-post-cat-pill, .breadcrumbs a'
    );

    targets.forEach(el => {
      // 1. Lưu lại nội dung gốc ban đầu
      if (el.dataset.rawText === undefined) {
        el.dataset.rawText = el.textContent.trim();
      }

      const raw = el.dataset.rawText;

      // 2. Nếu có chứa dấu phân cách "|"
      if (raw.includes('|')) {
        const parts = raw.split('|').map(s => s.trim());
        el.textContent = (lang === 'en' ? parts[1] : parts[0]) || parts[0];
      } else {
        // Cơ chế An toàn (Graceful Fallback)
        el.textContent = raw;
      }
    });
  }

  function applyLanguage(lang, save) {
    // 1. Update dropdown toggle text
    var flagEl = document.getElementById('current-lang-flag');
    var textEl = document.getElementById('current-lang-text');
    if (flagEl && textEl) {
      if (lang === 'en') {
        flagEl.textContent = '🇬🇧';
        textEl.textContent = 'EN';
      } else {
        flagEl.textContent = '🇻🇳';
        textEl.textContent = 'VI';
      }
    }

    // Close dropdown
    var dropdown = document.getElementById('lang-dropdown-menu');
    if (dropdown) {
      dropdown.classList.remove('show');
    }

    // 2. Toggle in-post bilingual content blocks
    var viContents = document.querySelectorAll("[data-lang='vi']");
    var enContents = document.querySelectorAll("[data-lang='en']");

    if (lang === 'en') {
      viContents.forEach(el => { el.style.display = 'none'; });
      enContents.forEach(el => { el.style.display = 'block'; });
    } else {
      enContents.forEach(el => { el.style.display = 'none'; });
      viContents.forEach(el => { el.style.display = 'block'; });
    }

    // 3. Apply VI | EN syntax parsing
    applyBilingualElements(lang);

    // 4. Translate static dictionary terms (optional, depending on where data-i18n is used in template)
    var i18nTargets = document.querySelectorAll('[data-i18n]');
    i18nTargets.forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (CORE_I18N[lang] && CORE_I18N[lang][key]) {
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
          el.placeholder = CORE_I18N[lang][key];
        } else {
          el.textContent = CORE_I18N[lang][key];
        }
      }
    });

    // Save to localStorage
    if (save !== false) {
      try { localStorage.setItem(STORAGE_KEY, lang); } catch(e) {}
    }

    // Dispatch event to inform Auto TOC and others to update
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang: lang } }));
  }

  // Global function called from inline onclick
  window.setLanguage = function(lang) {
    applyLanguage(lang, true);
  };

  // Legacy support for switchLanguage
  window.switchLanguage = window.setLanguage;

  // Close dropdown when clicking outside
  document.addEventListener('click', function(event) {
    var toggleBtn = document.getElementById('lang-toggle-btn');
    var dropdown = document.getElementById('lang-dropdown-menu');
    if (toggleBtn && dropdown) {
      if (!toggleBtn.contains(event.target) && !dropdown.contains(event.target)) {
        dropdown.classList.remove('show');
      }
    }
  });

  document.addEventListener('DOMContentLoaded', initBilingual);
})();


/* ==========================================
   READING PROGRESS BAR & READING TIME
   ========================================== */
(function() {
  'use strict';

  // Reading Progress Bar (throttled for perf)
  var progressBar = null;
  var ticking = false;

  function updateProgress() {
    if (!progressBar) return;
    var winScroll = window.pageYOffset || document.documentElement.scrollTop;
    var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    var pct = height > 0 ? Math.min(100, (winScroll / height) * 100) : 0;
    progressBar.style.width = pct + '%';
    ticking = false;
  }

  window.addEventListener('scroll', function() {
    if (!ticking) {
      requestAnimationFrame(updateProgress);
      ticking = true;
    }
  }, { passive: true });

  // Reading Time Calculator
  function calcReadingTime() {
    var postBody = document.querySelector('.post-body');
    var readTimeEl = document.getElementById('reading-time-val');
    if (!postBody || !readTimeEl) return;

    var text = postBody.innerText || postBody.textContent || '';
    var words = text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
    // ~200 wpm for Vietnamese readers
    var minutes = Math.max(1, Math.ceil(words / 200));
    readTimeEl.innerText = minutes + ' phút đọc';
  }

  // Copy share link button
  function initCopyLink() {
    var copyBtn = document.getElementById('copy-link-btn');
    if (!copyBtn) return;
    copyBtn.addEventListener('click', function() {
      var url = window.location.href;
      if (navigator.clipboard) {
        navigator.clipboard.writeText(url).then(function() {
          showCopiedToast();
        }).catch(function() {
          fallbackCopy(url);
        });
      } else {
        fallbackCopy(url);
      }
    });
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch(e) {}
    document.body.removeChild(ta);
    showCopiedToast();
  }

  function showCopiedToast() {
    var existing = document.getElementById('copied-toast');
    if (existing) existing.remove();

    var toast = document.createElement('div');
    toast.id = 'copied-toast';
    toast.innerText = '✅ Đã sao chép link!';
    toast.style.cssText = [
      'position: fixed',
      'bottom: 1.5rem',
      'left: 50%',
      'transform: translateX(-50%)',
      'background: #0f172a',
      'color: #fff',
      'padding: 0.65rem 1.35rem',
      'border-radius: 9999px',
      'font-size: 0.88rem',
      'font-weight: 600',
      'z-index: 9999',
      'box-shadow: 0 4px 20px rgba(0,0,0,0.3)',
      'animation: fadeInUp 0.3s ease'
    ].join(';');

    // Inject keyframe once
    if (!document.getElementById('toast-keyframe')) {
      var style = document.createElement('style');
      style.id = 'toast-keyframe';
      style.textContent = '@keyframes fadeInUp { from { opacity:0; transform: translateX(-50%) translateY(10px); } to { opacity:1; transform: translateX(-50%) translateY(0); } }';
      document.head.appendChild(style);
    }

    document.body.appendChild(toast);
    setTimeout(function() {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s ease';
      setTimeout(function() { toast.remove(); }, 350);
    }, 2200);
  }

  // Scroll-to-top button
  function initScrollTop() {
    var btn = document.getElementById('scroll-top-btn');
    if (!btn) return;
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  document.addEventListener('DOMContentLoaded', function() {
    progressBar = document.querySelector('.reading-progress-bar');
    calcReadingTime();
    initCopyLink();
    initScrollTop();
  });
})();


/**
 * FOOTER SCRIPTS — Modular Footer (FEAT-MODULAR-FOOTER-V3)
 * - Scroll-to-top button
 */
(function () {
  'use strict';

  function initScrollToTop() {
    var btn = document.getElementById('scroll-to-top');
    if (!btn) return;
    btn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
