  document.addEventListener('DOMContentLoaded', initScrollToTop);
})();


/**
 * Blogger Special Posts Widget Engine v2.1
 * Multi-label Support & Pluggable Pattern Strategy
 * Spec: FEAT-FLEXIBLE-SPECIAL-POSTS-WIDGET-V2
 *
 * Features:
 *  - Multi-label fetch (parallel) với deduplication
 *  - SessionStorage cache 5 phút
 *  - 4 renderers: ranked, spotlight, quote, digest
 *  - Skeleton shimmer (CLS = 0)
 *  - Anchor scroll highlight pulse
 *  - Label sanitization (lọc @ # _ ~)
 *  - Fallback: views → latest nếu API lỗi
 */
(function () {
  'use strict';

  /* ─── Constants ─────────────────────────────────────────────── */
  const CACHE_PREFIX = 'editorial_sp_';
  const CACHE_TTL    = 5 * 60 * 1000; // 5 phút

  /* ─── Pattern → Renderer map (Pluggable Strategy) ───────────── */
  const PATTERN_RENDERERS = {
    ranked:    renderRankedPattern,
    spotlight: renderSpotlightPattern,
    quote:     renderQuotePattern,
    digest:    renderDigestPattern,
    // Mở rộng tương lai: video, slideshow
  };

  /* ═══════════════════════════════════════════════════════════════
     INIT
     ═══════════════════════════════════════════════════════════════ */
  document.addEventListener('DOMContentLoaded', function () {
    initSpecialPostWidgets();
    initAnchorHighlight();
  });

  function initSpecialPostWidgets() {
    // Tự động nhận diện nếu user bấm "+ Thêm tiện ích" HTML/JavaScript mới và gõ cú pháp ngắn gọn
    document.querySelectorAll('.widget.HTML .widget-content, .widget.HTML').forEach(el => {
      if (el.querySelector('.special-posts-widget')) return;
      const targetHost = el.querySelector('.widget-content') || el;
      const directContent = targetHost.textContent.trim();
      const match = directContent.match(/^(?:pattern|kiểu)\s*:\s*(spotlight|ranked|quote|digest)/i);
      if (match) {
        const pattern = match[1].toLowerCase();
        const wrapper = document.createElement('div');
        wrapper.className = 'special-posts-widget';
        wrapper.dataset.pattern = pattern;
        const configDiv = document.createElement('div');
        configDiv.className = 'sp-raw-user-content';
        configDiv.style.display = 'none';
        configDiv.textContent = directContent.replace(/^(?:pattern|kiểu)\s*:\s*(spotlight|ranked|quote|digest)\s*\|?/i, '').trim();
        wrapper.appendChild(configDiv);
        targetHost.innerHTML = '';
        targetHost.appendChild(wrapper);
      }
    });

    const widgets = document.querySelectorAll('.special-posts-widget');
    widgets.forEach(renderWidgetInstance);
  }

  /* ═══════════════════════════════════════════════════════════════
     RENDER WIDGET INSTANCE
     ═══════════════════════════════════════════════════════════════ */
  async function renderWidgetInstance(container) {
    // ── Hỗ trợ cấu hình nhanh từ ô Content của Blogger Layout ──
    const userConfigEl = container.querySelector('.sp-raw-user-content');
    if (userConfigEl) {
      const rawUserContent = userConfigEl.innerHTML.trim();
      // Case A: Người dùng dán nguyên thẻ .special-posts-widget
      if (userConfigEl.querySelector('.special-posts-widget')) {
        const replacement = userConfigEl.querySelector('.special-posts-widget');
        container.replaceWith(replacement);
        return renderWidgetInstance(replacement);
      }
      // Case B: Người dùng dán mã HTML nhúng bên thứ 3 (AdSense, Banner, iframe, custom HTML...)
      if (/<(script|iframe|img|picture|a|form|object|embed)/i.test(rawUserContent) || (rawUserContent.startsWith('<') && !rawUserContent.includes('data-pattern') && !rawUserContent.includes('data-labels'))) {
        container.innerHTML = rawUserContent;
        container.classList.remove('special-posts-widget');
        return;
      }
      // Case C: Người dùng chỉ gõ tên nhãn dạng văn bản (VD: "Triết lý", "label: Sách", "labels: A, B | limit: 3")
      const textOnly = userConfigEl.textContent.trim();
      if (textOnly) {
        const parts = textOnly.split('|').map(s => s.trim());
        parts.forEach(part => {
          if (/^limit\s*:\s*(\d+)/i.test(part)) {
            container.dataset.limit = part.match(/^limit\s*:\s*(\d+)/i)[1];
          } else if (/^sort\s*:\s*(\w+)/i.test(part)) {
            container.dataset.sort = part.match(/^sort\s*:\s*(\w+)/i)[1];
          } else if (/^(?:thumb|thumbnail)\s*:\s*(true|false)/i.test(part)) {
            container.dataset.showThumbnail = part.match(/^(?:thumb|thumbnail)\s*:\s*(true|false)/i)[1].toLowerCase();
          } else if (/^snippet\s*:\s*(true|false)/i.test(part)) {
            container.dataset.showSnippet = part.match(/^snippet\s*:\s*(true|false)/i)[1].toLowerCase();
          } else if (/^(?:viewall|viewAllText)\s*:\s*(.+)/i.test(part)) {
            container.dataset.viewAllText = part.match(/^(?:viewall|viewAllText)\s*:\s*(.+)/i)[1].trim();
          } else if (/^(?:timerange|timeRange)\s*:\s*(\w+)/i.test(part)) {
            container.dataset.timeRange = part.match(/^(?:timerange|timeRange)\s*:\s*(\w+)/i)[1].trim();
          } else if (/^(?:posts|links)\s*:\s*(.+)/i.test(part)) {
            container.dataset.posts = part.match(/^(?:posts|links)\s*:\s*(.+)/i)[1].trim();
          } else if (/^title\s*:\s*(.+)/i.test(part)) {
            container.dataset.title = part.match(/^title\s*:\s*(.+)/i)[1].trim();
          } else {
            const cleanedLabel = part.replace(/^(labels?|nhãn)\s*:\s*/i, '').trim();
            if (cleanedLabel) container.dataset.labels = cleanedLabel;
          }
        });
      }
      userConfigEl.remove();
    }

    // Nếu widget đã có markup tĩnh (static preview demo) và không có cấu hình fetch
    if (!container.dataset.labels && !container.dataset.posts && !container.dataset.sort && container.querySelector('.sp-widget-card')) {
      return;
    }

    const pattern        = container.dataset.pattern  || 'digest';
    const rawLabels      = (container.dataset.labels  || container.dataset.label || '').trim();
    const limit          = Math.min(parseInt(container.dataset.limit, 10) || 4, 10);
    const sort           = container.dataset.sort     || 'latest';
    const handpickedRaw  = container.dataset.posts    || '';
    const showThumb      = container.dataset.showThumbnail !== 'false';
    const showSnippet    = container.dataset.showSnippet   !== 'false';
    const viewAllText    = container.dataset.viewAllText   || 'Xem tất cả »';
    const widgetTitle    = container.dataset.title         || '';

    // Thêm class pattern cho container queries
    container.classList.add('pattern-' + pattern);

    // Skeleton loading trước — CLS = 0
    renderSkeleton(container, pattern, limit, widgetTitle, viewAllText, rawLabels);

    try {
      let posts = [];

      if (handpickedRaw.trim()) {
        // Chế độ Handpicked URLs
        posts = await fetchHandpickedPosts(handpickedRaw);
      } else if (sort === 'views' || sort === 'popular') {
        // Chế độ Popular Posts (số lượt xem)
        const timeRange = container.dataset.timeRange || 'all_time';
        try {
          posts = await fetchPopularPosts(limit, timeRange, rawLabels);
        } catch (e) {
          // Fallback về latest nếu API Popular Posts không khả dụng
          console.warn('[SpecialPostsWidget] Popular Posts API không khả dụng, fallback → latest', e);
          if (rawLabels) {
            const labelList = splitLabels(rawLabels);
            posts = await fetchMultiLabelPosts(labelList, limit, 'latest');
          }
        }
      } else if (rawLabels) {
        // Chế độ Multi-label
        const labelList = splitLabels(rawLabels);
        posts = await fetchMultiLabelPosts(labelList, limit, sort);
      }

      if ((!posts || posts.length === 0) && typeof window !== 'undefined' && window.__SPECIAL_POSTS_MOCK__) {
        var mockAll = window.__SPECIAL_POSTS_MOCK__;
        if (rawLabels) {
          var lList = splitLabels(rawLabels).map(function(l) { return l.toLowerCase().replace(/^[@#_~]+/, ''); });
          posts = mockAll.filter(function(p) {
            var pLabels = (p.labels || []).map(function(l) { return l.toLowerCase().replace(/^[@#_~]+/, ''); });
            return lList.some(function(req) { return pLabels.indexOf(req) !== -1; });
          });
        }
        if (!posts || posts.length === 0) {
          posts = mockAll;
        }
        posts = posts.slice(0, limit);
      }

      if (!posts || posts.length === 0) {
        renderEmptyState(container, widgetTitle, viewAllText, rawLabels);
        return;
      }

      // Gọi Pattern Renderer
      const renderer = PATTERN_RENDERERS[pattern] || PATTERN_RENDERERS.digest;
      container.innerHTML = buildWidgetShell(
        widgetTitle,
        viewAllText,
        rawLabels,
        pattern,
        renderer(posts, { showThumb, showSnippet, limit })
      );

    } catch (err) {
      if (typeof window !== 'undefined' && window.__SPECIAL_POSTS_MOCK__) {
        var mockAll = window.__SPECIAL_POSTS_MOCK__;
        var posts = mockAll.slice(0, limit);
        var renderer = PATTERN_RENDERERS[pattern] || PATTERN_RENDERERS.digest;
        container.innerHTML = buildWidgetShell(
          widgetTitle,
          viewAllText,
          rawLabels,
          pattern,
          renderer(posts, { showThumb, showSnippet, limit })
        );
        return;
      }
      console.warn('[SpecialPostsWidget] Lỗi nạp dữ liệu:', err);
      container.innerHTML = buildWidgetShell(
        widgetTitle,
        viewAllText,
        rawLabels,
        pattern,
        '<div class="sp-error">Không thể tải nội dung mục này.</div>'
      );
    }
  }

  /* ═══════════════════════════════════════════════════════════════
     SKELETON LOADING
     ═══════════════════════════════════════════════════════════════ */
  function renderSkeleton(container, pattern, limit, title, viewAllText, rawLabels) {
    let skeletonBody = '';

    if (pattern === 'spotlight') {
      skeletonBody = `
        <div class="sp-skeleton" style="padding:0.75rem 1rem 1rem;">
          <div class="sp-skeleton-cover"></div>
          <div class="sp-skeleton-line sp-skeleton-line-55" style="margin-bottom:0.75rem;height:10px;"></div>
          <div class="sp-skeleton-line sp-skeleton-line-full" style="height:16px;margin-bottom:0.4rem;"></div>
          <div class="sp-skeleton-line sp-skeleton-line-80"  style="height:16px;margin-bottom:0.9rem;"></div>
          <div class="sp-skeleton-line sp-skeleton-line-40"  style="height:10px;"></div>
          <div class="sp-skeleton-line sp-skeleton-line-55"  style="height:10px;margin-top:0.35rem;"></div>
          <div class="sp-skeleton-line sp-skeleton-line-40"  style="height:10px;margin-top:0.35rem;"></div>
        </div>`;

    } else if (pattern === 'quote') {
      skeletonBody = `
        <div class="sp-skeleton" style="padding:1.1rem 1.25rem;">
          <div class="sp-skeleton-quote-line" style="width:20px;height:22px;margin-bottom:0.5rem;"></div>
          <div class="sp-skeleton-quote-line sp-skeleton-line-full"></div>
          <div class="sp-skeleton-quote-line sp-skeleton-line-80"></div>
          <div class="sp-skeleton-quote-line sp-skeleton-line-55"></div>
          <div class="sp-skeleton-quote-line" style="width:20px;height:22px;margin-left:auto;margin-top:0.25rem;"></div>
          <div class="sp-skeleton-quote-line sp-skeleton-line-40" style="margin-left:auto;margin-top:0.75rem;"></div>
        </div>`;

    } else {
      // ranked & digest — dạng danh sách
      const items = Array.from({ length: limit }).map(() => `
        <div class="sp-skeleton-item">
          ${pattern === 'ranked' ? '<div class="sp-skeleton-num"></div>' : ''}
          <div class="sp-skeleton-thumb"></div>
          <div class="sp-skeleton-content">
            <div class="sp-skeleton-line sp-skeleton-line-full"></div>
            <div class="sp-skeleton-line sp-skeleton-line-80"></div>
            <div class="sp-skeleton-line sp-skeleton-line-40"></div>
          </div>
        </div>`).join('');
      skeletonBody = `<div class="sp-skeleton">${items}</div>`;
    }

    container.innerHTML = buildWidgetShell(title, viewAllText, rawLabels, pattern, skeletonBody);
  }

  /* ═══════════════════════════════════════════════════════════════
     WIDGET SHELL — Header + Body
     ═══════════════════════════════════════════════════════════════ */
  function buildWidgetShell(title, viewAllText, rawLabels, pattern, bodyHtml) {
    const cleanTitle = title ? escapeHtml(title) : '';
    const viewAllUrl = rawLabels
      ? buildLabelUrl(splitLabels(rawLabels)[0])
      : '/';

    const headerHtml = cleanTitle ? `
      <div class="sp-widget-header">
        <h3 class="sp-widget-title">${cleanTitle}</h3>
        <a href="${escapeHtml(viewAllUrl)}" class="sp-view-all-link">${escapeHtml(viewAllText)}</a>
      </div>` : '';

    return `
      <div class="sp-widget-card pattern-${escapeHtml(pattern)}">
        ${headerHtml}
        <div class="sp-widget-body">
          ${bodyHtml}
        </div>
      </div>`;
  }

  function renderEmptyState(container, title, viewAllText, rawLabels) {
    container.innerHTML = buildWidgetShell(
      title, viewAllText, rawLabels, 'empty',
      '<div class="sp-empty-state">Chưa có nội dung trong mục này.</div>'
    );
  }

  /* ═══════════════════════════════════════════════════════════════
     PATTERN RENDERERS
     ═══════════════════════════════════════════════════════════════ */

  /* ── 1. RANKED ──────────────────────────────────────────────── */
  function renderRankedPattern(posts, opts) {
    const lang = (() => { try { return localStorage.getItem('user_lang') || 'vi'; } catch(e) { return 'vi'; } })();
    const itemsHtml = posts.map((post, index) => {
      const rankNum = String(index + 1).padStart(2, '0');
      const thumb   = (opts.showThumb && post.thumbnail)
        ? optimizeThumbnail(post.thumbnail, 's160-c')
        : '';
      const aiType  = extractAIType(post.labels || []);
      const aiHtml  = aiType ? (' • ' + renderAIInlineBadge(aiType)) : '';

      return `
        <a href="${escapeHtml(post.url)}" class="sp-ranked-item"${aiType ? ` data-ai-type="${aiType}"` : ''}>
          <span class="sp-rank-number">${rankNum}</span>
          ${thumb ? `<div class="sp-ranked-thumb"><img src="${escapeHtml(thumb)}" alt="${escapeHtml(post.title)}" loading="lazy" width="52" height="52"/></div>` : ''}
          <div class="sp-ranked-content">
            <h4 class="sp-ranked-title">${escapeHtml(post.title)}</h4>
            <span class="sp-ranked-date">${escapeHtml(post.dateFormatted)}${aiHtml}</span>
          </div>
        </a>`;
    }).join('');

    return `<div class="special-posts-ranked-list">${itemsHtml}</div>`;
  }

  /* ── 2. SPOTLIGHT ───────────────────────────────────────────── */
  function renderSpotlightPattern(posts, opts) {
    // Chỉ lấy bài đầu tiên làm hero
    const post   = posts[0];
    const lang   = (() => { try { return localStorage.getItem('user_lang') || 'vi'; } catch(e) { return 'vi'; } })();
    const thumb  = (opts.showThumb && post.thumbnail)
      ? optimizeThumbnail(post.thumbnail, 's600-c')
      : '';
    const badge  = post.labels && post.labels[0]
      ? formatLabelName(post.labels[0])
      : '';
    const aiType = extractAIType(post.labels || []);
    const aiHtml = aiType ? renderAIStandardBadge(aiType, lang) : '';

    return `
      <a href="${escapeHtml(post.url)}" class="sp-spotlight-card"${aiType ? ` data-ai-type="${aiType}"` : ''}>
        ${thumb ? `<div class="sp-spotlight-cover"><img src="${escapeHtml(thumb)}" alt="${escapeHtml(post.title)}" loading="lazy" width="600" height="338"/></div>` : ''}
        <div class="sp-spotlight-info">
          <div class="sp-spotlight-meta">
            ${badge ? `<span class="sp-spotlight-badge">${escapeHtml(badge)}</span>` : ''}
            <span class="sp-spotlight-date">📅 ${escapeHtml(post.dateFormatted)}</span>
            ${aiHtml}
          </div>
          <h3 class="sp-spotlight-title">${escapeHtml(post.title)}</h3>
          ${(opts.showSnippet && post.snippet) ? `<p class="sp-spotlight-snippet">${escapeHtml(post.snippet)}</p>` : ''}
          <span class="sp-spotlight-cta">Đọc tiếp bài viết <span aria-hidden="true">→</span></span>
        </div>
      </a>`;
  }

  /* ── 3. QUOTE ───────────────────────────────────────────────── */
  function renderQuotePattern(posts, opts) {
    const itemsHtml = posts.map(post => {
      // Lấy tiêu đề bài làm câu trích dẫn, snippet làm lời bình
      const quoteText = post.title;
      const snippet   = (opts.showSnippet && post.snippet) ? post.snippet : '';

      return `
        <a href="${escapeHtml(post.url)}" class="sp-quote-card">
          <span class="sp-quote-mark-open">\u201C</span>
          <p class="sp-quote-text">${escapeHtml(quoteText)}</p>
          <span class="sp-quote-mark-close">\u201D</span>
          <div class="sp-quote-author">\u2014 ${escapeHtml(post.dateFormatted)}</div>
          ${snippet ? `<div class="sp-quote-divider"></div><p class="sp-quote-snippet">${escapeHtml(snippet)}</p>` : ''}
          <span class="sp-quote-cta">Xem lời bình &amp; phân tích <span aria-hidden="true">→</span></span>
        </a>`;
    }).join('');

    return `<div class="sp-quote-list">${itemsHtml}</div>`;
  }

  /* ── 4. DIGEST ──────────────────────────────────────────────── */
  function renderDigestPattern(posts, opts) {
    const lang = (() => { try { return localStorage.getItem('user_lang') || 'vi'; } catch(e) { return 'vi'; } })();
    const itemsHtml = posts.map(post => {
      const snippet = (opts.showSnippet && post.snippet) ? post.snippet : '';
      const aiType  = extractAIType(post.labels || []);
      const aiHtml  = aiType ? (' • ' + renderAIInlineBadge(aiType)) : '';

      return `
        <a href="${escapeHtml(post.url)}" class="sp-digest-item"${aiType ? ` data-ai-type="${aiType}"` : ''}>
          <div class="sp-digest-timestamp">
            <span class="sp-digest-bullet">✦</span>
            ${escapeHtml(post.dateFormatted)}${aiHtml}
          </div>
          <div class="sp-digest-title">${escapeHtml(post.title)}</div>
          ${snippet ? `<div class="sp-digest-snippet">${escapeHtml(snippet)}</div>` : ''}
        </a>`;
    }).join('');

    return `<div class="sp-digest-list">${itemsHtml}</div>`;
  }

  /* ═══════════════════════════════════════════════════════════════
     DATA FETCHERS
     ═══════════════════════════════════════════════════════════════ */

  /* ── Fetch nhiều nhãn song song + deduplication ─────────────── */
  async function fetchMultiLabelPosts(labels, limit, sort) {
    // Nạp song song tất cả nhãn
    const promises = labels.map(label => fetchSingleLabelFeed(label, limit + 5));
    const results  = await Promise.all(promises);

    // Gộp
    const allPosts = results.flat();

    // Khử trùng lặp theo URL
    const uniqueMap = new Map();
    allPosts.forEach(post => {
      if (!uniqueMap.has(post.url)) uniqueMap.set(post.url, post);
    });
    let merged = Array.from(uniqueMap.values());

    // Sắp xếp
    if (sort === 'random') {
      merged.sort(() => Math.random() - 0.5);
    } else {
      // latest (mặc định)
      merged.sort((a, b) => new Date(b.published) - new Date(a.published));
    }

    return merged.slice(0, limit);
  }

  /* ── Fetch 1 nhãn qua Blogger JSON Feed API ─────────────────── */
  async function fetchSingleLabelFeed(label, count) {
    const cacheKey = CACHE_PREFIX + 'label_' + encodeURIComponent(label) + '_' + count;
    const cached   = readCache(cacheKey);
    if (cached) return cached;

    const encodedLabel = encodeURIComponent(label);
    const blogUrl      = getBlogBaseUrl();
    const url          = `${blogUrl}/feeds/posts/summary/-/${encodedLabel}?alt=json&max-results=${count}&orderby=published`;

    const res  = await fetch(url);
    const json = await res.json();

    const posts = parseFeedEntries(json.feed ? json.feed.entry : []);
    writeCache(cacheKey, posts);
    return posts;
  }

  /* ── Fetch Popular Posts (lượt xem nhiều nhất) ──────────────── */
  async function fetchPopularPosts(limit, timeRange, labelFilter) {
    const cacheKey = CACHE_PREFIX + 'popular_' + timeRange + '_' + limit;
    const cached   = readCache(cacheKey);
    if (cached) {
      return filterByLabels(cached, labelFilter, limit);
    }

    // Blogger Popular Posts JSON Feed
    const blogUrl = getBlogBaseUrl();
    // Blogger không có Public Popular Posts API trực tiếp;
    // dùng feed với orderby=updated (phổ biến nhất) kết hợp max-results lớn
    // và sắp xếp theo label nếu có
    let url;
    if (labelFilter) {
      const labelList    = splitLabels(labelFilter);
      const encodedLabel = encodeURIComponent(labelList[0]);
      url = `${blogUrl}/feeds/posts/summary/-/${encodedLabel}?alt=json&max-results=20&orderby=updated`;
    } else {
      url = `${blogUrl}/feeds/posts/summary?alt=json&max-results=20&orderby=updated`;
    }

    const res  = await fetch(url);
    const json = await res.json();

    const posts = parseFeedEntries(json.feed ? json.feed.entry : []);
    writeCache(cacheKey, posts);
    return posts.slice(0, limit);
  }

  /* ── Fetch các bài viết theo danh sách URL chỉ định ─────────── */
  async function fetchHandpickedPosts(rawUrls) {
    const urls = rawUrls.split(',')
      .map(u => u.trim())
      .filter(Boolean);

    const blogBase = getBlogBaseUrl();

    const promises = urls.map(async (relOrAbs) => {
      const absUrl   = relOrAbs.startsWith('http') ? relOrAbs : blogBase + relOrAbs;
      const feedUrl  = absUrl.includes('?')
        ? absUrl + '&alt=json'
        : absUrl + '?alt=json';
      const cacheKey = CACHE_PREFIX + 'post_' + encodeURIComponent(absUrl);
      const cached   = readCache(cacheKey);
      if (cached) return cached;

      try {
        const res  = await fetch(feedUrl);
        const json = await res.json();
        const entry = json.entry;
        if (!entry) return null;
        const post = parseEntry(entry);
        writeCache(cacheKey, post);
        return post;
      } catch {
        return null;
      }
    });

    const results = await Promise.all(promises);
    return results.filter(Boolean);
  }

  /* ═══════════════════════════════════════════════════════════════
     PARSER HELPERS
     ═══════════════════════════════════════════════════════════════ */

  function parseFeedEntries(entries) {
    if (!Array.isArray(entries)) return [];
    return entries.map(parseEntry).filter(Boolean);
  }

  function parseEntry(entry) {
    try {
      // URL bài viết
      const links  = entry.link || [];
      const altLink = links.find(l => l.rel === 'alternate');
      const url    = altLink ? altLink.href : '';

      // Tiêu đề
      const title = entry.title ? (entry.title.$t || '') : '';

      // Ảnh thumbnail
      let thumbnail = '';
      if (entry.media$thumbnail) {
        thumbnail = entry.media$thumbnail.url || '';
      }

      // Snippet
      let snippet = '';
      if (entry.summary) {
        snippet = (entry.summary.$t || '').replace(/<[^>]+>/g, '').trim();
      } else if (entry.content) {
        snippet = (entry.content.$t || '').replace(/<[^>]+>/g, '').trim().substring(0, 200);
      }

      // Ngày đăng
      const published = entry.published ? entry.published.$t : '';
      const dateFormatted = formatDate(published);

      // Labels
      const labels = (entry.category || []).map(c => c.term || '');

      return { url, title, thumbnail, snippet, published, dateFormatted, labels };
    } catch {
      return null;
    }
  }

  /* ═══════════════════════════════════════════════════════════════
     UTILS
     ═══════════════════════════════════════════════════════════════ */

  /** Lọc ký tự @ # _ ~ khỏi tên nhãn trước khi hiển thị */
  function formatLabelName(raw) {
    if (!raw) return '';
    return decodeURIComponent(String(raw)).replace(/^[@#_~]+/, '').trim();
  }

  /** Trích xuất loại AI từ mảng labels; trả về key hoặc null */
  function extractAIType(labels) {
    if (!labels || !labels.length) return null;
    for (var i = 0; i < labels.length; i++) {
      var raw = labels[i] || '';
      var lower = raw.toLowerCase().replace(/-/g, ':');
      if (lower.startsWith('ai:')) return lower;
    }
    return null;
  }

  /** Render AI badge inline HTML (không phụ thuộc external module để tránh race condition) */
  function renderAIInlineBadge(aiType) {
    var icons = { 'ai:assisted': '✨', 'ai:product': '🤖', 'ai:generated': '⚡' };
    var icon = icons[aiType] || '✨';
    return '<span class="ai-badge ai-badge-inline" data-ai-type="' + aiType + '" data-ai-variant="inline">' +
      '<span class="ai-badge-icon">' + icon + '</span>' +
      '<span class="ai-badge-label">AI</span>' +
    '</span>';
  }

  function renderAIStandardBadge(aiType, lang) {
    var icons = { 'ai:assisted': '✨', 'ai:product': '🤖', 'ai:generated': '⚡' };
    var labels = {
      'ai:assisted':  { vi: 'Hỗ trợ bởi AI', en: 'AI-Assisted'  },
      'ai:product':   { vi: 'Sản phẩm AI',   en: 'AI Product'   },
      'ai:generated': { vi: 'Tạo bởi AI',    en: 'AI-Generated' },
    };
    var icon = icons[aiType] || '✨';
    var labelCfg = labels[aiType] || labels['ai:assisted'];
    var label = (lang === 'en') ? labelCfg.en : labelCfg.vi;
    return '<span class="ai-badge ai-badge-standard" data-ai-type="' + aiType + '" data-ai-variant="standard">' +
      '<span class="ai-badge-icon">' + icon + '</span>' +
      '<span class="ai-badge-label">' + label + '</span>' +
    '</span>';
  }

  /** Tách chuỗi nhãn "A, B, C" thành mảng */
  function splitLabels(raw) {
    if (!raw) return [];
    const cleaned = raw.replace(/^(labels?|nhãn)\s*:\s*/i, '');
    return cleaned.split(',').map(l => l.trim()).filter(Boolean);
  }

  /** Tối ưu kích thước ảnh Blogger (Retina-safe) */
  function optimizeThumbnail(url, size) {
    if (!url) return '';
    return url
      .replace(/\/s[0-9]+(-c)?\//, '/' + size + '/')
      .replace(/\/w[0-9]+-h[0-9]+(-c)?\//, '/' + size + '/');
  }

  /** Format ngày ISO thành DD/MM/YYYY */
  function formatDate(iso) {
    if (!iso) return '';
    try {
      const d = new Date(iso);
      const dd   = String(d.getDate()).padStart(2, '0');
      const mm   = String(d.getMonth() + 1).padStart(2, '0');
      const yyyy = d.getFullYear();
      return `${dd}/${mm}/${yyyy}`;
    } catch { return ''; }
  }

  /** Lấy base URL của blog hiện tại */
  function getBlogBaseUrl() {
    return window.location.protocol + '//' + window.location.host;
  }

  /** Build URL trang nhãn (lọc @ cho URL) */
  function buildLabelUrl(label) {
    if (!label) return '/';
    const blogBase = getBlogBaseUrl();
    return `${blogBase}/search/label/${encodeURIComponent(label)}`;
  }

  /** Lọc bài viết theo danh sách nhãn (OR logic) */
  function filterByLabels(posts, rawLabels, limit) {
    if (!rawLabels) return posts.slice(0, limit);
    const labels = splitLabels(rawLabels);
    const filtered = posts.filter(p =>
      p.labels && p.labels.some(l => labels.includes(l))
    );
    return (filtered.length > 0 ? filtered : posts).slice(0, limit);
  }

  /** Escape HTML để tránh XSS */
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  /* ═══════════════════════════════════════════════════════════════
     SESSION STORAGE CACHE
     ═══════════════════════════════════════════════════════════════ */

  function readCache(key) {
    try {
      const raw = sessionStorage.getItem(key);
      if (!raw) return null;
      const { data, ts } = JSON.parse(raw);
      if (Date.now() - ts > CACHE_TTL) {
        sessionStorage.removeItem(key);
        return null;
      }
      return data;
    } catch { return null; }
  }

  function writeCache(key, data) {
    try {
      sessionStorage.setItem(key, JSON.stringify({ data, ts: Date.now() }));
    } catch { /* Quota exceeded — bỏ qua */ }
  }

  /* ═══════════════════════════════════════════════════════════════
     ANCHOR SCROLL HIGHLIGHT
     Khi URL chứa #widget-{slug}, cuộn mượt + kích hoạt pulse
     ═══════════════════════════════════════════════════════════════ */
  function initAnchorHighlight() {
    function handleHash(hash) {
      if (!hash) return;
      const el = document.querySelector(hash);
      if (el && el.classList.contains('special-posts-widget')) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.classList.add('sp-anchor-highlight');
        setTimeout(() => el.classList.remove('sp-anchor-highlight'), 1800);
      }
    }

    // Xử lý hash lúc trang load
    if (window.location.hash) {
      // Đợi widget render xong
      setTimeout(() => handleHash(window.location.hash), 600);
    }

    // Xử lý khi hash thay đổi (bấm link trong trang)
    window.addEventListener('hashchange', () => handleHash(window.location.hash));
  }

})();


/* ==========================================
   AI TRANSPARENCY SYSTEM — FEAT-AI-TRANSPARENCY-V1
   Spec: specs/AI_TRANSPARENCY_SPECIFICATION.md

   Chức năng:
   - Nhận diện nhãn ai:assisted / ai:product / ai:generated
   - Render 4 biến thể badge: full, standard, micro, inline
   - Render Khung Thông Cáo Minh Bạch (Disclosure Box) ở đầu bài
   - Hỗ trợ song ngữ VI/EN, tự động cập nhật khi languageChanged
   - Hoàn toàn độc lập, không ảnh hưởng đến filter/category logic
   ========================================== */
(function () {
  'use strict';

  /* ─── Cấu hình nhãn AI ─────────────────────────────────────── */
  var AI_TYPES = {
    'ai:assisted':  { icon: '✨', vi: 'Hỗ trợ bởi AI', en: 'AI-Assisted'  },
    'ai:product':   { icon: '🤖', vi: 'Sản phẩm AI',   en: 'AI Product'   },
    'ai:generated': { icon: '⚡', vi: 'Tạo bởi AI',    en: 'AI-Generated' },
  };

  /* Nội dung Khung Thông Cáo Minh Bạch */
  var DISCLOSURE_TEXT = {
    'ai:assisted': {
      vi: 'Bài viết này được thực hiện với sự hỗ trợ của công cụ Trí tuệ Nhân tạo (AI) trong khâu nghiên cứu tư liệu, tra cứu dữ liệu và gợi ý cấu trúc dàn ý. Toàn bộ góc nhìn, trải nghiệm thực tế, văn phong và việc kiểm chứng tính chính xác của thông tin đều do Nam Trương trực tiếp thực hiện và chịu trách nhiệm.',
      en: 'This article was researched and outlined with the assistance of Artificial Intelligence (AI) tools. All viewpoints, personal insights, narrative voice, and rigorous fact-checking are conducted and owned entirely by Nam Truong.',
    },
    'ai:product': {
      vi: 'Bài viết này là đánh giá, trải nghiệm thực tế của tác giả về một sản phẩm hoặc công cụ AI. Mọi nhận xét đều dựa trên trải nghiệm cá nhân, không bị ảnh hưởng bởi nhà sản xuất.',
      en: 'This article is an honest review and personal experience of an AI product or tool. All opinions are based on personal use and are independent from the product makers.',
    },
    'ai:generated': {
      vi: 'Toàn bộ hoặc phần lớn nội dung của bài viết này được tổng hợp bởi AI theo yêu cầu của tác giả, nhằm mục đích thử nghiệm công nghệ và nghiên cứu. Tác giả chịu trách nhiệm về việc lựa chọn và công bố nội dung.',
      en: 'Most or all of this article\'s content was generated by AI as a technology experiment directed by the author. The author takes responsibility for selecting and publishing this content.',
    },
  };

  /* ─── Nhận diện ngôn ngữ hiện tại ──────────────────────────── */
  function getCurrentLang() {
    try {
      return localStorage.getItem('user_lang') || 'vi';
    } catch (e) {
      return 'vi';
    }
  }

  /* ─── Chuẩn hóa nhãn AI (không phân biệt hoa thường, hỗ trợ dấu gạch ngang) */
  function normalizeAILabel(str) {
    if (!str) return '';
    return str.toLowerCase().replace(/-/g, ':');
  }

  /* ─── Phát hiện loại AI từ chuỗi nhãn đơn ─────────────────── */
  function detectAIType(labelStr) {
    var normalized = normalizeAILabel(labelStr.trim());
    // Khớp trực tiếp
    if (AI_TYPES[normalized]) return normalized;
    // Khớp từng key
    var keys = Object.keys(AI_TYPES);
    for (var i = 0; i < keys.length; i++) {
      if (normalized.indexOf(keys[i].replace(':', ':')) === 0 ||
          normalized.indexOf(keys[i].replace(':', '-')) === 0) {
        return keys[i];
      }
    }
    return null;
  }

  /* ─── Phát hiện loại AI từ mảng nhãn ───────────────────────── */
  function detectAITypeFromLabels(labels) {
    if (!labels || !labels.length) return null;
    for (var i = 0; i < labels.length; i++) {
      var raw = (typeof labels[i] === 'string') ? labels[i] : (labels[i].name || '');
      var type = detectAIType(raw);
      if (type) return type;
    }
    return null;
  }

  /* ─── Render Badge HTML ─────────────────────────────────────── */
  /**
   * @param {string} type     - 'ai:assisted' | 'ai:product' | 'ai:generated'
   * @param {string} variant  - 'full' | 'standard' | 'micro' | 'inline'
   * @param {string} lang     - 'vi' | 'en'
   * @returns {string} HTML string
   */
  function renderAIBadge(type, variant, lang) {
    type = detectAIType(type) || type;
    var cfg = AI_TYPES[type];
    if (!cfg) return '';

    var label = (lang === 'en') ? cfg.en : cfg.vi;
    var icon  = cfg.icon;

    if (variant === 'inline') {
      return (
        '<span class="ai-badge ai-badge-inline" data-ai-type="' + type + '" data-ai-variant="inline">' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">AI</span>' +
        '</span>'
      );
    }

    if (variant === 'micro') {
      return (
        '<span class="ai-badge ai-badge-micro" data-ai-type="' + type + '" data-ai-variant="micro">' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">AI</span>' +
        '</span>'
      );
    }

    if (variant === 'full') {
      return (
        '<button type="button" class="ai-badge ai-badge-full" data-ai-type="' + type + '" data-ai-variant="full" aria-expanded="false">' +
          '<span class="ai-badge-icon">' + icon + '</span>' +
          '<span class="ai-badge-label">' + label + '</span>' +
          '<span class="ai-badge-chevron">▾</span>' +
        '</button>'
      );
    }

    // standard (default)
    return (
      '<span class="ai-badge ai-badge-standard" data-ai-type="' + type + '" data-ai-variant="standard">' +
        '<span class="ai-badge-icon">' + icon + '</span>' +
        '<span class="ai-badge-label">' + label + '</span>' +
      '</span>'
    );
  }

  /* ─── Render Disclosure Box HTML ────────────────────────────── */
  function renderDisclosureBox(type, lang) {
    type = detectAIType(type) || type;
    var cfg  = AI_TYPES[type];
    var disc = DISCLOSURE_TEXT[type];
    if (!cfg || !disc) return '';

    var label    = (lang === 'en') ? cfg.en : cfg.vi;
    var bodyText = (lang === 'en') ? disc.en : disc.vi;
    var titleVI  = '✦ THÔNG CÁO MINH BẠCH VỀ NỘI DUNG';
    var titleEN  = '✦ AI TRANSPARENCY DISCLOSURE';
    var title    = (lang === 'en') ? titleEN : titleVI;
    var learnVI  = 'ℹ️ Tìm hiểu thêm về Chính sách AI của chúng tôi »';
    var learnEN  = 'ℹ️ Learn more about our AI Policy »';
    var learnTxt = (lang === 'en') ? learnEN : learnVI;
    var toggleVI = 'Xem chi tiết';
    var toggleEN = 'Details';
    var toggleTxt = (lang === 'en') ? toggleEN : toggleVI;

    return (
      '<div class="ai-disclosure-box" data-ai-type="' + type + '" id="ai-disclosure-box">' +
        '<div class="ai-disclosure-header" id="ai-disclosure-header" role="button" tabindex="0" aria-expanded="false" aria-controls="ai-disclosure-body">' +
          '<div class="ai-disclosure-title">' +
            '<span class="ai-disclosure-icon">' + cfg.icon + '</span>' +
            '<span class="ai-disclosure-title-text" data-vi="' + titleVI + '" data-en="' + titleEN + '">' + title + '</span>' +
          '</div>' +
          '<button type="button" class="ai-disclosure-toggle" aria-controls="ai-disclosure-body">' +
            '<span class="ai-disclosure-toggle-text" data-vi="' + toggleVI + '" data-en="' + toggleEN + '">' + toggleTxt + '</span>' +
            '<span class="ai-disclosure-toggle-icon">▾</span>' +
          '</button>' +
        '</div>' +
        '<div class="ai-disclosure-body" id="ai-disclosure-body">' +
          '<div class="ai-disclosure-text">' +
            '<p data-vi="' + escapeAttr(disc.vi) + '" data-en="' + escapeAttr(disc.en) + '">' + escapeHtml(bodyText) + '</p>' +
            '<a href="#" class="ai-disclosure-learn-more" data-vi="' + escapeAttr(learnVI) + '" data-en="' + escapeAttr(learnEN) + '">' + escapeHtml(learnTxt) + '</a>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  /* ─── Cập nhật ngôn ngữ tất cả badges đang hiển thị ────────── */
  function updateAllBadgesLanguage(lang) {
    // Cập nhật standard và full badge labels
    var badges = document.querySelectorAll('.ai-badge[data-ai-type][data-ai-variant]');
    badges.forEach(function (badge) {
      var type    = badge.getAttribute('data-ai-type');
      var variant = badge.getAttribute('data-ai-variant');
      var cfg     = AI_TYPES[type];
      if (!cfg) return;

      var labelEl = badge.querySelector('.ai-badge-label');
      if (!labelEl) return;

      if (variant === 'full' || variant === 'standard') {
        labelEl.textContent = (lang === 'en') ? cfg.en : cfg.vi;
      }
      // micro/inline: luôn hiển thị "AI" — không đổi
    });

    // Cập nhật Disclosure Box
    var box = document.getElementById('ai-disclosure-box');
    if (box) {
      // Title
      var titleEl = box.querySelector('.ai-disclosure-title-text');
      if (titleEl) {
        titleEl.textContent = (lang === 'en') ? titleEl.getAttribute('data-en') : titleEl.getAttribute('data-vi');
      }
      // Toggle text
      var toggleEl = box.querySelector('.ai-disclosure-toggle-text');
      if (toggleEl) {
        toggleEl.textContent = (lang === 'en') ? toggleEl.getAttribute('data-en') : toggleEl.getAttribute('data-vi');
      }
      // Body paragraph
      var bodyEl = box.querySelector('.ai-disclosure-text p');
      if (bodyEl) {
        bodyEl.textContent = (lang === 'en') ? bodyEl.getAttribute('data-en') : bodyEl.getAttribute('data-vi');
      }
      // Learn more link
      var learnEl = box.querySelector('.ai-disclosure-learn-more');
      if (learnEl) {
        learnEl.textContent = (lang === 'en') ? learnEl.getAttribute('data-en') : learnEl.getAttribute('data-vi');
      }
    }
  }

  /* ─── ĐIỂM TÍCH HỢP 1: Single Post Header (Full Badge + Disclosure Box) */
  function injectSinglePostBadge() {
    var container = document.getElementById('single-post-wrapper');
    if (container) {
      if (container.style.display === 'none') return;
    } else {
      container = document.querySelector('.single-post-container');
      if (!container) return;
    }

    // Đọc ai type từ data attribute trên container hoặc bài viết
    var rawType = container.getAttribute('data-ai-type');
    if (!rawType) {
      var childWithAI = container.querySelector('[data-ai-type]');
      if (childWithAI) rawType = childWithAI.getAttribute('data-ai-type');
    }
    if (!rawType) return;
    var aiType = detectAIType(rawType);
    if (!aiType || !AI_TYPES[aiType]) return;

    var lang = getCurrentLang();

    // (A) Inject Full Badge vào author-meta-details
    var metaDetails = container.querySelector('.author-meta-details');
    if (metaDetails && !metaDetails.querySelector('.ai-badge-full')) {
      // Thêm dấu phân cách và badge
      var sepEl = document.createElement('span');
      sepEl.textContent = '•';
      metaDetails.appendChild(sepEl);

      var wrapper = document.createElement('span');
      wrapper.innerHTML = renderAIBadge(aiType, 'full', lang);
      metaDetails.appendChild(wrapper);

      // Gắn sự kiện toggle cho Full Badge
      initFullBadgeToggle(wrapper.querySelector('.ai-badge-full'));
    }

    // (B) Inject Disclosure Box trước .post-body (hoặc trước AdSense top)
    var postBody = container.querySelector('.post-body');
    var adsenseTop = container.querySelector('.adsense-slot.adsense-top, .adsense-top');
    var insertBefore = adsenseTop || postBody;

    if (insertBefore && !container.querySelector('#ai-disclosure-box')) {
      var discEl = document.createElement('div');
      discEl.innerHTML = renderDisclosureBox(aiType, lang);
      insertBefore.parentNode.insertBefore(discEl.firstChild, insertBefore);

      // Gắn sự kiện toggle cho Disclosure Box
      initDisclosureBoxToggle();
    }
  }

  /* Toggle Full Badge → mở/đóng Disclosure Box */
  function initFullBadgeToggle(badgeEl) {
    if (!badgeEl) return;
    badgeEl.addEventListener('click', function () {
      var box = document.getElementById('ai-disclosure-box');
      if (!box) return;
      var isOpen = box.classList.toggle('is-open');
      badgeEl.setAttribute('aria-expanded', isOpen);
      badgeEl.classList.toggle('is-open', isOpen);
    });
  }

  /* Toggle Disclosure Box header */
  function initDisclosureBoxToggle() {
    var header = document.getElementById('ai-disclosure-header');
    if (!header) return;

    function toggle() {
      var box = header.closest('.ai-disclosure-box');
      if (!box) return;
      var isOpen = box.classList.toggle('is-open');
      header.setAttribute('aria-expanded', isOpen);
    }

    header.addEventListener('click', toggle);
    header.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        toggle();
      }
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 2: Post Cards Feed (Standard Badge) ────── */
  function injectPostCardBadges() {
    var lang = getCurrentLang();
    var cards = document.querySelectorAll('.post-card[data-ai-type]');
    cards.forEach(function (card) {
      var rawType = card.getAttribute('data-ai-type');
      var aiType = detectAIType(rawType);
      if (!aiType || !AI_TYPES[aiType]) return;

      var meta = card.querySelector('.post-card-meta');
      if (!meta) return;

      // Tránh inject trùng
      if (meta.querySelector('.ai-badge-standard')) return;

      // Thêm separator và badge
      var sepEl = document.createElement('span');
      sepEl.textContent = '•';

      var wrapper = document.createElement('span');
      wrapper.style.display = 'inline-flex';
      wrapper.innerHTML = renderAIBadge(aiType, 'standard', lang);

      meta.appendChild(sepEl);
      meta.appendChild(wrapper);
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 3: Archive Timeline (Micro Badge) ──────── */
  function injectTimelineBadges() {
    var lang = getCurrentLang();
    // archive-page.js đã render .archive-post-card với data-ai-type
    var cards = document.querySelectorAll('.archive-post-card[data-ai-type]');
    cards.forEach(function (card) {
      var rawType = card.getAttribute('data-ai-type');
      var aiType = detectAIType(rawType);
      if (!aiType || !AI_TYPES[aiType]) return;

      // Tránh inject trùng
      if (card.querySelector('.ai-badge-micro')) return;

      // Tìm title span và inject badge ngay sau
      var titleEl = card.querySelector('.archive-post-card-title');
      if (!titleEl) return;

      var wrapper = document.createElement('span');
      wrapper.innerHTML = renderAIBadge(aiType, 'micro', lang);
      titleEl.after(wrapper.firstChild);
    });
  }

  /* ─── ĐIỂM TÍCH HỢP 4: Special Post Widgets (Inline Badge) ─── */
  function injectWidgetBadges() {
    var lang = getCurrentLang();

    // Ranked widget: inject vào .sp-ranked-date
    var rankedDates = document.querySelectorAll('.sp-ranked-item[data-ai-type] .sp-ranked-date');
    rankedDates.forEach(function (dateEl) {
      var item = dateEl.closest('[data-ai-type]');
      if (!item) return;
      var rawType = item.getAttribute('data-ai-type');
      var aiType = detectAIType(rawType);
      if (!aiType || !AI_TYPES[aiType]) return;
      if (dateEl.querySelector('.ai-badge-inline')) return;

      var sepEl = document.createElement('span');
      sepEl.textContent = ' • ';
      var wrapper = document.createElement('span');
      wrapper.innerHTML = renderAIBadge(aiType, 'inline', lang);
      dateEl.appendChild(sepEl);
      dateEl.appendChild(wrapper.firstChild);
    });

    // Spotlight widget: inject vào .sp-spotlight-meta
    var spotlightMetas = document.querySelectorAll('.sp-spotlight-card[data-ai-type] .sp-spotlight-meta');
    spotlightMetas.forEach(function (metaEl) {
      var card = metaEl.closest('[data-ai-type]');
      if (!card) return;
      var rawType = card.getAttribute('data-ai-type');
      var aiType = detectAIType(rawType);
      if (!aiType || !AI_TYPES[aiType]) return;
      if (metaEl.querySelector('.ai-badge-standard')) return;

      var wrapper = document.createElement('span');
      wrapper.innerHTML = renderAIBadge(aiType, 'standard', lang);
      metaEl.appendChild(wrapper.firstChild);
    });

    // Digest widget: inject vào .sp-digest-timestamp
    var digestTimestamps = document.querySelectorAll('.sp-digest-item[data-ai-type] .sp-digest-timestamp');
    digestTimestamps.forEach(function (tsEl) {
      var item = tsEl.closest('[data-ai-type]');
      if (!item) return;
      var rawType = item.getAttribute('data-ai-type');
      var aiType = detectAIType(rawType);
      if (!aiType || !AI_TYPES[aiType]) return;
      if (tsEl.querySelector('.ai-badge-inline')) return;

      var sepEl = document.createElement('span');
      sepEl.textContent = ' • ';
      var wrapper = document.createElement('span');
      wrapper.innerHTML = renderAIBadge(aiType, 'inline', lang);
      tsEl.appendChild(sepEl);
      tsEl.appendChild(wrapper.firstChild);
    });
  }

  /* ─── Khởi chạy toàn bộ injection ─────────────────────────── */
  function initAITransparency() {
    injectSinglePostBadge();
    injectPostCardBadges();
    injectTimelineBadges();
    injectWidgetBadges();
  }

  /* ─── Lắng nghe sự kiện languageChanged từ bilingual.js ─────── */
  window.addEventListener('languageChanged', function (e) {
    var lang = (e.detail && e.detail.lang) ? e.detail.lang : getCurrentLang();
    updateAllBadgesLanguage(lang);
  });

  /* ─── MutationObserver: tự động inject khi DOM thay đổi ─────── */
  // (dùng cho archive-page.js và special-posts.js render bất đồng bộ)
  var _observer = null;
  function startObserver() {
    if (_observer) return;
    _observer = new MutationObserver(function (mutations) {
      var needsInject = mutations.some(function (m) {
        return m.addedNodes.length > 0;
      });
      if (needsInject) {
        injectTimelineBadges();
        injectWidgetBadges();
        injectPostCardBadges();
      }
    });
    _observer.observe(document.body, { childList: true, subtree: true });
  }

  /* ─── Utility: escape ────────────────────────────────────────── */
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function escapeAttr(str) {
    if (!str) return '';
    return String(str).replace(/"/g, '&quot;').replace(/'/g, '&#039;');
  }

  /* ─── Export API cho các module khác ───────────────────────── */
  window.AITransparency = {
    detectAIType: detectAIType,
    detectAITypeFromLabels: detectAITypeFromLabels,
    renderAIBadge: renderAIBadge,
    renderDisclosureBox: renderDisclosureBox,
    injectTimelineBadges: injectTimelineBadges,
    injectWidgetBadges: injectWidgetBadges,
    injectPostCardBadges: injectPostCardBadges,
    reinject: initAITransparency,
  };

  /* ─── Khởi động ─────────────────────────────────────────────── */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      initAITransparency();
      startObserver();
    });
  } else {
    initAITransparency();
    startObserver();
  }

})();


/**
 * HOMEPAGE INTERLEAVED WIDGETS & MAIN FEED CONTROLLER
 * Feature: FEAT-HOMEPAGE-INTERLEAVED-WIDGETS-V1
 * 
 * Manages 3-tier main feed layout:
 * 1. Above Feed Hero (#main-above-feed) - Auto hides on Page 2+
 * 2. In-Feed Interleaved (#main-in-feed-section) - Auto-injects after post 3 (or data-insert-after)
 * 3. Pre-Pagination Action Zone (#main-pre-pagination-section) - Positioned immediately above .blog-pager
 */

(function () {
  'use strict';

  function initInFeedInterleaving() {
    const inFeedSection = document.getElementById('main-in-feed-section');
    if (!inFeedSection) return;

    // 1. Kiểm tra xem có widget hoặc nội dung không
    const hasWidgets = inFeedSection.querySelectorAll('.widget, .special-posts-widget, .infeed-custom-content').length > 0 ||
                       (inFeedSection.children.length > 0 && inFeedSection.textContent.trim().length > 0);

    if (!hasWidgets) {
      inFeedSection.style.display = 'none';
      return;
    }

    // 2. Lấy danh sách các bài viết
    const feedContainer = document.getElementById('posts-feed-container') || document.querySelector('.posts-feed');
    if (!feedContainer) {
      inFeedSection.style.display = 'none';
      return;
    }

    const posts = feedContainer.querySelectorAll('.post-card');
    if (!posts || posts.length === 0) {
      inFeedSection.style.display = 'none';
      return;
    }

    // 3. Xác định vị trí chèn (Mặc định: sau bài số 3 -> index 2)
    let insertAfterIndex = 2;
    const customConfigWidget = inFeedSection.querySelector('[data-insert-after]');
    if (customConfigWidget) {
      const customNum = parseInt(customConfigWidget.dataset.insertAfter, 10);
      if (!isNaN(customNum) && customNum > 0) {
        insertAfterIndex = customNum - 1;
      }
    }

    // Đảm bảo không vượt quá tổng số bài hiện có
    const targetIndex = Math.min(insertAfterIndex, posts.length - 1);

    // 4. Di chuyển mượt mà vào giữa luồng
    posts[targetIndex].after(inFeedSection);
    inFeedSection.classList.add('in-feed-active');
    inFeedSection.style.display = 'block';
  }

  function initPrePaginationSection() {
    const prePagination = document.getElementById('main-pre-pagination-section');
    if (!prePagination) return;

    // Kiểm tra widget / nội dung
    const hasWidgets = prePagination.querySelectorAll('.widget, .special-posts-widget, .newsletter-card, .adsense-slot, .ads-banner, .pre-pagination-card').length > 0 ||
                       (prePagination.children.length > 0 && prePagination.textContent.trim().length > 0);

    if (!hasWidgets) {
      prePagination.style.display = 'none';
      return;
    }

    // Tìm nút phân trang blog-pager
    const blogPager = document.querySelector('.blog-pager');
    if (blogPager && blogPager.parentElement) {
      blogPager.before(prePagination);
      prePagination.style.display = 'block';
    } else {
      prePagination.style.display = 'block';
    }
  }

  function initAboveFeedSection() {
    const aboveFeed = document.getElementById('main-above-feed');
    if (!aboveFeed) return;

    // Kiểm tra nếu là trang chi tiết bài viết (Single Post) hoặc trang lưu trữ (Archive)
    const singlePostWrapper = document.getElementById('single-post-wrapper');
    const isSinglePost = document.body.classList.contains('view-single') ||
                         (singlePostWrapper && singlePostWrapper.style.display !== 'none');

    const archiveWrapper = document.getElementById('archive-page-wrapper');
    const isArchivePage = document.body.classList.contains('view-archive') ||
                          (archiveWrapper && archiveWrapper.style.display !== 'none');

    if (isSinglePost || isArchivePage) {
      aboveFeed.style.display = 'none';
      return;
    }

    // Kiểm tra nếu là Trang 2 trở đi (Page 2+)
    const urlParams = new URLSearchParams(window.location.search);
    const isPaged = urlParams.has('updated-max') ||
                    urlParams.get('page') === '2' ||
                    urlParams.get('paged') === '2' ||
                    document.body.classList.contains('is-paged') ||
                    document.body.classList.contains('view-paged');

    if (isPaged) {
      aboveFeed.style.display = 'none';
      return;
    }

    // Kiểm tra rỗng
    const hasWidgets = aboveFeed.querySelectorAll('.widget, .special-posts-widget, .hero-spotlight').length > 0 ||
                       (aboveFeed.children.length > 0 && aboveFeed.textContent.trim().length > 0);

    if (!hasWidgets) {
      aboveFeed.style.display = 'none';
      return;
    }

    aboveFeed.style.display = 'block';
  }

  function initProfileCoverSection() {
    const coverWrapper = document.getElementById('cover-image-wrapper');
    if (!coverWrapper) return;

    // Ưu tiên 1: Ảnh tải lên trực tiếp từ máy tính qua widget Image1 (Tải Lên Ảnh Bìa)
    const uploadedBannerEl = document.getElementById('profile-uploaded-banner');
    if (uploadedBannerEl && uploadedBannerEl.textContent.trim()) {
      coverWrapper.style.backgroundImage = `url("${uploadedBannerEl.textContent.trim()}")`;
    }

    const configEl = document.getElementById('profile-custom-config');
    if (!configEl) return;

    const rawContent = configEl.innerHTML.trim();
    if (!rawContent) return;

    // Case 1: Người dùng dán nguyên khối HTML tùy chỉnh hoàn toàn
    if (configEl.querySelector('.profile-cover-section') || (rawContent.startsWith('<') && !rawContent.includes('banner:') && !rawContent.includes('avatar:'))) {
      const coverSection = document.getElementById('profile-cover-section');
      if (coverSection) {
        coverSection.outerHTML = rawContent;
      }
      return;
    }

    // Case 2: Người dùng dán link ảnh hoặc cú pháp ngắn
    const textOnly = configEl.textContent.trim();
    if (textOnly) {
      const coverWrapper = document.getElementById('cover-image-wrapper');
      const avatarImg = document.getElementById('profile-avatar-img');
      const bioEl = document.getElementById('profile-author-bio');
      const nameEl = document.getElementById('profile-author-name');

      // Nếu chỉ dán mỗi link ảnh (http...)
      if (/^https?:\/\/[^\s]+$/i.test(textOnly)) {
        if (coverWrapper) {
          coverWrapper.style.backgroundImage = `url("${textOnly}")`;
        }
      } else {
        // Cú pháp: banner: https://... | avatar: https://... | bio: ... | name: ...
        const parts = textOnly.split('|').map(s => s.trim());
        parts.forEach(part => {
          if (/^banner\s*:\s*(https?:\/\/[^\s]+)/i.test(part)) {
            const url = part.match(/^banner\s*:\s*(https?:\/\/[^\s]+)/i)[1];
            if (coverWrapper) coverWrapper.style.backgroundImage = `url("${url}")`;
          } else if (/^avatar\s*:\s*(https?:\/\/[^\s]+)/i.test(part)) {
            const url = part.match(/^avatar\s*:\s*(https?:\/\/[^\s]+)/i)[1];
            if (avatarImg) avatarImg.src = url;
          } else if (/^bio\s*:\s*(.+)/i.test(part)) {
            const bio = part.match(/^bio\s*:\s*(.+)/i)[1].trim();
            if (bioEl) bioEl.textContent = bio;
          } else if (/^name\s*:\s*(.+)/i.test(part)) {
            const name = part.match(/^name\s*:\s*(.+)/i)[1].trim();
            if (nameEl) nameEl.textContent = name;
          } else if (/^https?:\/\/[^\s]+/i.test(part)) {
            if (coverWrapper) coverWrapper.style.backgroundImage = `url("${part.trim()}")`;
          }
        });
      }
    }
  }

  function initHomepageInterleavedWidgets() {
    initProfileCoverSection();
    initAboveFeedSection();
    initInFeedInterleaving();
    initPrePaginationSection();
  }

  // Khởi chạy khi DOM sẵn sàng
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHomepageInterleavedWidgets);
  } else {
    initHomepageInterleavedWidgets();
  }

  // Expose ra window để các module khác hoặc preview sandbox có thể kích hoạt lại khi chuyển view
  window.initHomepageInterleavedWidgets = initHomepageInterleavedWidgets;
})();

  //
